func parseClipVolume(raw, flag string) (any, error) {
	if raw == "inherit" {
		return nil, nil
	}
	value, err := strconv.ParseFloat(raw, 64)
	if err != nil || value < 0 || value > 2 {
		return nil, fmt.Errorf("%s must be a number from 0 to 2, or inherit", flag)
	}
	return value, nil
}

